import { animals, calculateResult } from './data.js';
import { contactPage } from './contact.js';
import {brandStory,runMotion} from './motion.js';
const basePath=new URL('.',import.meta.url).pathname;
const appURL=p=>p.startsWith(basePath)?p:basePath+p.replace(/^\/+/, '');
const localizeMarkup=html=>html.replace(/src="\/assets\//g,'src="'+basePath+'assets/').replace(/href="\/(?!\/)/g,'href="'+basePath);
const clayImage=(name,alt)=>`<img class="clay-icon" src="/assets/${name}.png" alt="${alt}" width="600" height="600" decoding="async">`;
function brandName(test){return test?'나의 기질·성향 찾기':'애니어그램 인사이트 <span class="brand-association">애니어그램 협의회</span>'}
const app=document.querySelector('#app');
const icons={spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M5 16v5h14v-5"/>',share:'<circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8.5 10.5 7-4m-7 7 7 4"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="m3 6 9 7 9-7"/>',heart:'<path d="M12 20 4 12a5 5 0 0 1 8-6 5 5 0 0 1 8 6Z"/>',book:'<path d="M12 6c-3-2-6-2-9-1v14c3-1 6-1 9 1 3-2 6-2 9-1V5c-3-1-6-1-9 1Zm0 0v14"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 4v3"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.spark}</svg>`;
const image=(a,cls='')=>`<img class="${cls}" src="/assets/animal-${a.id}.png" alt="전신 3D 클레이 ${a.name}" loading="lazy" width="600" height="600">`;
const link=(href,text,cls='button')=>`<a href="${href}" class="${cls}" data-link>${text}</a>`;
function header(test=false){return `<header class="header"><a href="/" class="brand" data-link><img src="/assets/logo-3d.png" alt="" width="38" height="38"><span>${test?'animal insight':'insight'}<small>${brandName(test)}</small></span></a><nav aria-label="주 메뉴"><a href="/#about" data-link>인사이트 소개</a><a href="/education/" data-link ${location.pathname.includes('education')?'aria-current="page"':''}>교육 소개</a><a href="/lectures/" data-link ${location.pathname.includes('lectures')?'aria-current="page"':''}>강연 소개</a><a href="/contact/" data-link ${location.pathname.includes('contact')?'aria-current="page"':''}>문의하기</a><a href="/test/" class="mobile-test-nav" data-link>나의 동물 유형 찾기</a></nav><div class="header-actions">${link('/test/','나의 동물 유형 찾기','button small orange')}<button class="menu-toggle icon-button" aria-label="메뉴 열기" aria-expanded="false">${icon('menu')}</button></div></header>`}
function footer(test=false){return `<footer class="footer"><div class="footer-top"><a href="/" class="brand" data-link><img src="/assets/logo-3d.png" alt="" width="38" height="38"><span>${test?'animal insight':'insight'}<small>${brandName(test)}</small></span></a><p>나를 이해하는 작은 시작,<br>더 나은 관계로 이어지는 인사이트.</p><div class="footer-links">${link('/education/','교육 소개','')}${link('/lectures/','강연 소개','')}${link('/contact/','문의하기','')}</div></div><div class="footer-bottom"><div>${test?'':'<span>상호명 애니어그램 인사이트</span><span>애니어그램 협의회</span>'}<span>대표 이은규</span><span>주소 서울시 강서구 화곡본동</span><a href="tel:01040492697">연락처 010-4049-2697</a><a href="mailto:leejinho970715@gmail.com">leejinho970715@gmail.com</a></div><p>© ${new Date().getFullYear()} INSIGHT. All rights reserved.</p></div></footer>`}
function home(){return `${header()}<main id="main"><section class="hero"><div class="hero-copy"><span class="eyebrow"><i></i> A LITTLE INSIGHT, A BIG DIFFERENCE</span><h1>나를 알아가는,<br>가장 <span class="orange-text">다정한 방법.</span></h1><p>우리는 모두 다른 모습, 다른 마음을 가지고 있어요.<br>나를 발견하고 서로를 이해하는 여정,<br>애니어그램 인사이트와 함께 시작해요.</p><div class="hero-buttons">${link('/test/',`${icon('spark')} 나의 동물 유형 찾기`,'button orange')}${link('/#about','인사이트 만나보기','text-link')}</div><div class="hero-note">${icon('clock')} 약 5분 · 45문항 · 나를 위한 작은 발견</div></div><div class="hero-art"><span class="orbit-label top">HELLO, MY TRUE SELF!</span><img class="hero-image" src="/assets/hero-transparent.png" alt="둥근 단상 위에 모인 9가지 귀여운 클레이 동물" width="1536" height="1024" fetchpriority="high"><div class="floating-tag tag-one">${icon('heart')} 서로 달라도, 함께</div><div class="floating-tag tag-two">${icon('spark')} 나다움을 발견!</div><span class="art-caption">9 PERSONALITIES. ENDLESS POSSIBILITIES.</span></div><div class="hero-bottom"><span>DISCOVER YOURSELF. CONNECT WITH OTHERS.</span><a href="#brand-story" aria-label="브랜드 이야기로 스크롤" class="scroll-circle">↓</a><span>SCROLL TO EXPLORE</span></div></section>${brandStory()}<div class="ticker" aria-hidden="true"><div>UNDERSTAND YOURSELF <b>✳</b> EMBRACE OUR DIFFERENCES <b>✳</b> GROW TOGETHER <b>✳</b> UNDERSTAND YOURSELF <b>✳</b> EMBRACE OUR DIFFERENCES <b>✳</b></div></div><section id="about" class="section about"><div class="section-heading reveal"><span class="eyebrow">01 / ABOUT INSIGHT</span><div><h2>나를 아는 만큼,<br>우리의 세상은 넓어져요.</h2><p>다름을 이해하면 관계가 달라집니다.<br>인사이트는 자기 이해를 넘어, 함께 성장하는 방법을 전합니다.</p></div></div><div class="about-grid"><article class="about-card reveal"><div class="card-top"><span>01</span>${icon('spark')}</div><h3>나를 발견하는 시간</h3><p>반복되는 나의 선택과 마음의 움직임.<br>익숙했던 나를 새로운 시선으로 만나요.</p><div class="about-animal pale-orange">${clayImage("about-discover","돋보기와 별 모양의 3D 클레이 자기 발견 아이콘")}<span>DISCOVER</span></div></article><article class="about-card reveal"><div class="card-top"><span>02</span>${icon('heart')}</div><h3>다름을 이해하는 마음</h3><p>나와 다른 사람을 이해하는 첫걸음.<br>판단 대신 호기심으로 관계를 바라봐요.</p><div class="about-animal pale-green">${clayImage("about-connect","말풍선과 하트 모양의 3D 클레이 공감 아이콘")}<span>CONNECT</span></div></article><article class="about-card reveal"><div class="card-top"><span>03</span>${icon('users')}</div><h3>함께 성장하는 경험</h3><p>일상과 팀에 적용할 수 있는 배움.<br>작은 인사이트가 더 나은 변화를 만들어요.</p><div class="about-animal pale-purple">${clayImage("about-grow","계단과 새싹 모양의 3D 클레이 함께 성장 아이콘")}<span>GROW</span></div></article></div></section><section id="business" class="section business"><div class="section-heading reveal"><span class="eyebrow">02 / WHAT WE DO</span><div><h2>이해가 경험이 되고,<br>경험이 변화가 되도록.</h2><p>개인의 발견에서 조직의 소통까지.<br>우리에게 필요한 배움을 연결합니다.</p></div></div><div class="business-grid"><a href="/education/" data-link class="business-card education-card reveal"><div class="card-top"><span>EDUCATION</span>${icon('book')}</div><h3>나를 이해하는 배움,<br>교육 프로그램</h3><p>기질의 이해부터 관계와 소통까지,<br>일상에 스며드는 체계적인 배움.</p><div class="business-card-bottom"><span class="pill">자기 이해</span><span class="pill">관계 · 소통</span><span class="card-action">교육 살펴보기 ${icon('plus')}</span></div></a><a href="/lectures/" data-link class="business-card lecture-card reveal"><div class="card-top"><span>LECTURE</span>${icon('users')}</div><h3>우리의 이야기가 되는,<br>인사이트 강연</h3><p>일상 속 공감과 참여로 함께하는 시간.<br>사람과 조직을 잇는 새로운 관점.</p><div class="business-card-bottom"><span class="pill">기업 · 기관</span><span class="pill">참여형 강연</span><span class="card-action">강연 살펴보기 ${icon('plus')}</span></div></a></div></section><section id="contact" class="section contact"><div class="test-banner reveal"><div><span class="eyebrow">03 / FIND YOUR INNER ANIMAL</span><h2>내 안에는<br>어떤 동물이 살고 있을까요?</h2><p>9가지 동물 유형으로 알아보는 나의 기질·성향.<br>가볍게 시작해서, 나에 대한 새로운 힌트를 발견해요.</p>${link('/test/',`${icon('spark')} 나의 동물 유형 찾기`,'button orange')}<div class="hero-note">약 5분 · 45문항 · 복수 선택 가능</div></div><div class="test-banner-art">${image(animals[6],'banner-monkey')}${image(animals[8],'banner-elephant')}<span class="round-sticker">JUST<br>BE YOU.</span></div></div><div class="animals-heading reveal"><h3>저마다 다른 매력, 9가지 동물 친구들</h3><p>어떤 친구가 나와 닮았는지 만나보세요.</p></div><div class="animal-gallery">${animals.map(a=>`<button class="animal-tile reveal" data-animal="${a.id}" style="--animal-bg:${a.color}">${image(a)}<span>${a.name}</span><small>TYPE ${String(a.id).padStart(2,'0')}</small></button>`).join('')}</div><div class="contact-line reveal"><div><span class="eyebrow">LET’S CONNECT</span><h3>함께하는 변화가 궁금하다면</h3><p>교육과 강연에 대해 편하게 이야기해주세요.</p></div><div>${link('mailto:leejinho970715@gmail.com',`${icon('mail')} 이메일로 문의하기`,'button dark')}<a href="tel:01040492697" class="phone-link">010-4049-2697</a></div></div></section></main>${footer()}`}
function education(){return `${header()}<main id="main"><section class="subhero"><div><span class="eyebrow">EDUCATION / 배움으로 만나는 나</span><h1>나를 이해하는 배움이<br><span class="orange-text">우리의 관계를 바꿉니다.</span></h1><p>아홉 가지 관점으로 나를 바라보고,<br>나와 다른 사람을 이해하는 언어를 배워요.</p>${link('/contact/','교육 문의하기','button orange')}</div><div class="subhero-art pale-green">${clayImage('education-icon','책과 학사모 모양의 3D 클레이 교육 아이콘')}<span>LEARN. UNDERSTAND. GROW.</span></div></section><section class="section"><div class="section-heading reveal"><span class="eyebrow">THE STORY</span><div><h2>에니어, 아홉 개의 관점</h2><p>사람의 동기와 반응을 아홉 가지 유형으로 살펴보는 자기 이해의 틀입니다.<br>유형은 사람을 단정하는 이름이 아니라, 나의 습관을 돌아보는 출발점이에요.</p></div></div><div class="timeline"><article class="reveal"><span>01 / SYMBOL</span><h3>아홉 점의 상징</h3><p>이름은 그리스어의 ‘아홉’과 ‘그림’에서 유래합니다. 원 위의 아홉 점을 통해 서로 다른 관점과 연결을 표현합니다.</p></article><article class="reveal"><span>02 / MODERN DEVELOPMENT</span><h3>현대의 자기 이해로</h3><p>20세기 오스카 이차조의 작업과 클라우디오 나란호의 접근이 현대 성격 유형 체계의 발전에 영향을 주었습니다.</p></article><article class="reveal"><span>03 / EVERYDAY PRACTICE</span><h3>일상과 관계 속으로</h3><p>나의 반복되는 반응을 알아차리고 다른 사람의 관점을 이해하는 데 활용됩니다. 하나의 유형으로 사람의 모든 모습을 설명하지는 않습니다.</p></article></div><a class="source-link" href="https://www.enneagraminstitute.com/the-traditional-enneagram/" target="_blank" rel="noopener noreferrer">역사 참고 자료 · The Enneagram Institute</a></section><section class="section soft-section"><div class="section-heading reveal"><span class="eyebrow">PROGRAMS</span><div><h2>이해에서 실천까지,<br>나의 속도로 배우는 과정</h2><p>애니어그램 협의회 전문 강사와 함께하는 교육 구성안입니다.<br>대상과 목적에 맞게 세부 일정과 내용을 조율합니다.</p></div></div><div class="program-grid">${[['01','자기 이해 기초','나를 발견하는 시작',['아홉 가지 기질과 핵심 동기','나의 습관과 강점 돌아보기','유형과 윙을 이해하는 연습']],['02','관계와 소통','다름을 연결하는 대화',['다른 관점으로 듣는 연습','관계 속 반복되는 갈등 살펴보기','서로에게 맞는 소통 방식 찾기']],['03','팀과 조직','함께 성장하는 실천',['팀 구성원의 강점 발견','협업과 피드백 대화 실습','우리 팀의 실천 계획 만들기']]].map(p=>`<article class="program-card reveal"><span class="eyebrow">COURSE ${p[0]}</span><h3>${p[1]}</h3><p>${p[2]}</p><ul>${p[3].map(t=>`<li>${icon('check')}${t}</li>`).join('')}</ul>${link('/contact/','교육 상담하기','button outline')}</article>`).join('')}</div></section><section class="section faq-section"><div><span class="eyebrow">Q & A</span><h2>배움 전에,<br>궁금한 이야기</h2></div><div class="faq"><details><summary>처음 접하는 사람도 참여할 수 있나요? ${icon('plus')}</summary><p>기초 과정은 처음 접하는 분을 위해 구성됩니다. 전문 용어보다는 일상 속 사례와 자기 관찰을 중심으로 시작합니다.</p></details><details><summary>기업이나 기관 단체 교육도 가능한가요? ${icon('plus')}</summary><p>대상, 인원, 교육 목적을 알려주시면 관계와 소통 또는 팀 협업을 중심으로 구성안을 상담합니다.</p></details><details><summary>교육 일정과 비용은 어떻게 확인하나요? ${icon('plus')}</summary><p>교육 일정, 소요 시간, 장소와 비용은 목적과 참여 규모에 따라 협의합니다. 이메일 또는 전화로 문의해주세요.</p></details></div></section></main>${footer()}`}
function lectures(){return `${header()}<main id="main"><section class="subhero"><div><span class="eyebrow">LECTURE / 마음을 잇는 이야기</span><h1>서로 다른 우리가<br><span class="orange-text">함께 성장하는 시간.</span></h1><p>일상의 이야기를 새로운 시선으로 바라보는 강연.<br>이해의 순간이 다음 행동으로 이어지도록 함께합니다.</p>${link('/contact/','강연 문의하기','button orange')}</div><div class="subhero-art pale-orange">${clayImage('lecture-icon','마이크와 말풍선 모양의 3D 클레이 강연 아이콘')}<span>A MOMENT OF INSIGHT.</span></div></section><section class="section greeting"><div class="greeting-title reveal"><span class="eyebrow">MEET YOUR SPEAKER</span><h2>안녕하세요,<br>강사 이은규입니다.</h2><span class="pill orange-pill">애니어그램 협의회 전문 강사</span></div><div class="greeting-body reveal"><span class="big-quote">“</span><h3>나를 이해하는 일이<br>서로를 향한 다정함이 되길 바랍니다.</h3><p>우리는 같은 상황에서도 다른 마음으로 반응합니다. 그 차이를 궁금해하는 순간, 나와 타인을 이해하는 새로운 길이 열립니다.</p><p>사람을 하나의 유형 안에 가두기보다, 각자의 강점을 발견하고 관계 속에서 실천하는 시간을 만들고 싶습니다. 함께 웃고 이야기하며 나다운 변화를 찾아가겠습니다.</p><strong>이은규 <span>강사</span></strong></div></section><section class="section soft-section"><div class="section-heading reveal"><span class="eyebrow">LECTURE THEMES</span><div><h2>우리에게 필요한<br>인사이트를 만나요.</h2><p>대상과 현장의 이야기에 맞춰 강연을 구성합니다.</p></div></div><div class="program-grid">${[['나를 만나는 인사이트','자기 이해 · 개인 성장','반복되는 선택과 반응을 돌아보고, 나만의 강점을 발견하는 시간.'],['다름을 잇는 대화','관계 · 소통','다양한 관점을 경험하고, 관계 속에서 공감을 표현하는 연습.'],['함께 일하는 우리','기업 · 팀 워크숍','팀원의 강점을 이해하고 협업에 적용할 수 있는 대화를 만드는 시간.']].map((p,i)=>`<article class="program-card reveal"><span class="eyebrow">0${i+1} / ${p[1]}</span><h3>${p[0]}</h3><p>${p[2]}</p>${link('/contact/','강연 상담하기','button outline')}</article>`).join('')}</div></section><section class="section lecture-history"><div class="section-heading reveal"><span class="eyebrow">OUR JOURNEY</span><div><h2>10회의 만남,<br>이어지는 발견.</h2><p>자기 이해와 관계, 소통을 주제로 이어온 강연.<br>회차별 일정과 현장 이야기는 정리해 소개할 예정입니다.</p></div></div><div class="history-strip reveal"><strong>10<span>회</span></strong><div><h3>인사이트 강연 진행</h3><p>각자의 이야기를 나누고, 새로운 관점을 만난 시간.</p></div><span class="pill">상세 이력 준비 중</span></div></section><section class="section book-section"><div class="book-art reveal"><div class="book-cover"><small>이은규 지음</small><h3>애니어그램으로<br>알아보는<br>내 자신</h3><img src="/assets/logo-3d.png" alt="인사이트 로고"><span>INSIGHT<br>나를 향한 작은 질문들</span></div><span class="book-caption">도서 표지 콘셉트</span></div><div class="reveal"><span class="eyebrow">THE NEXT CHAPTER</span><h2>나를 발견하는 이야기,<br>한 권의 책으로.</h2><h3>《애니어그램으로 알아보는 내 자신》</h3><p>강연에서 시작된 질문들을 일상의 언어로 담고 있습니다.<br>나의 마음을 관찰하고, 관계를 돌아보는 자기 이해의 여정.</p><span class="pill orange-pill">집필 중 · 출간 정보 추후 안내</span></div></section></main>${footer()}`}
let answers=Array.from({length:9},()=>[]),visited=Array(9).fill(false),step=0,phase='intro',preferredType,preferredWing;
try{const draft=JSON.parse(sessionStorage.getItem('animal-insight-draft'));if(draft&&draft.answers?.length===9&&draft.answers.every(a=>Array.isArray(a)&&a.every(v=>Number.isInteger(v)&&v>=0&&v<5))){answers=draft.answers;visited=draft.visited?.length===9?draft.visited.map(Boolean):visited;step=Math.min(8,Math.max(0,Number(draft.step)||0))}}catch{}
function saveDraft(){try{sessionStorage.setItem('animal-insight-draft',JSON.stringify({answers,visited,step}))}catch{}}
function intro(){const exists=visited.some(Boolean)||answers.some(a=>a.length);return `${header(true)}<main id="main" class="test-main"><section class="test-intro"><span class="eyebrow">MEET YOUR INNER ANIMAL</span><h1>내 안의 동물을<br><span class="orange-text">만나볼 시간.</span></h1><p>9가지 동물 유형으로 알아보는 나의 기질·성향.<br>평소의 나와 닮은 문장을 골라주세요.</p><div class="intro-animals">${image(animals[2])}${image(animals[1])}${image(animals[8])}</div><div class="test-facts"><span>${icon('clock')} 약 5분</span><span>${icon('check')} 45문항</span><span>${icon('users')} 복수 선택</span></div><div class="test-guide"><p>각 동물별 5개의 문장 중, 평소의 나와 닮은 문장을 <strong>모두</strong> 선택하세요.</p><p>닮은 문장이 없다면 ‘해당하는 문장 없음’을 선택할 수 있어요.</p><p>정답은 없어요. 되고 싶은 모습보다 평소의 모습을 떠올려주세요.</p></div><button class="button orange wide" data-start>${exists?'이어서 검사하기':'나의 동물 만나기'}</button>${exists?'<button class="text-link reset-draft" data-reset>처음부터 새로 시작하기</button>':''}<p class="test-disclaimer">자기 탐색을 위한 간단한 테스트로, 전문 검사나 진단을 대신하지 않습니다.<br>응답은 이 브라우저 탭에 임시 저장됩니다.</p></section></main>${footer(true)}`}
function questions(){const a=animals[step];return `${header(true)}<main id="main" class="test-main"><div class="quiz-shell"><div class="quiz-meta"><a href="/test/" data-intro>검사 소개</a><span>STEP ${String(step+1).padStart(2,'0')} / 09</span></div><div class="progress" role="progressbar" aria-label="검사 진행" aria-valuemin="0" aria-valuemax="9" aria-valuenow="${step+1}"><span style="width:${(step+1)/9*100}%"></span></div><div class="question-heading"><div><span class="eyebrow">나와 닮은 문장을 모두 골라주세요</span><h1>${a.name}의 마음,<br>나에게도 있나요?</h1><p>여러 개를 선택할 수 있어요. 평소의 나를 떠올려보세요.</p></div><div class="question-animal" style="background:${a.color}">${image(a)}</div></div><fieldset class="question-list"><legend class="sr-only">${a.name} 유형의 5개 문장</legend>${a.questions.map((q,i)=>`<label class="answer-option"><input type="checkbox" value="${i}" ${answers[step].includes(i)?'checked':''}><span class="check-box">${icon('check')}</span><span>${q}</span></label>`).join('')}<label class="answer-option none-option"><input type="checkbox" value="none" ${visited[step]&&!answers[step].length?'checked':''}><span class="check-box">${icon('check')}</span><span>해당하는 문장 없음</span></label></fieldset><p class="quiz-error" role="alert"></p><div class="quiz-actions"><button class="button outline" data-prev>${step?'이전':'소개로'}</button><span>${answers[step].length}개 선택</span><button class="button orange" data-next>${step===8?'결과 만나보기':'다음'}</button></div></div></main>${footer(true)}`}
function resultView(r){const a=animals[r.type-1];return `${header(true)}<main id="main" class="result-main"><div class="result-intro"><span class="eyebrow">HELLO, MY TRUE SELF</span><h1>나를 닮은 친구를 찾았어요!</h1><p>하나의 이름보다 풍부한, 나의 다양한 모습을 만나보세요.</p></div><section class="result-card" id="result-card"><div class="result-brand"><img src="/assets/logo-3d.png" alt="" width="28" height="28"><span>animal insight</span><small>나의 기질·성향 리포트</small></div><div class="result-primary"><div class="result-animal" style="background:${a.color}">${image(a)}</div><div><span class="result-type">${r.type}W${r.wing}</span><h2>${a.title}</h2><p class="result-tags">${a.tag}</p><p>${a.description}</p></div></div><div class="result-insights"><div><span>${icon('spark')} 나의 빛나는 강점</span><p>${a.gift}</p></div><div><span>${icon('heart')} 나를 위한 작은 연습</span><p>${a.growth}</p></div></div><div class="result-chart"><h3>내 안의 9가지 동물 비율</h3><p>선택한 문장 수를 전체 선택 수로 나눈 비율이에요.</p>${animals.map((an,i)=>`<div class="chart-row"><span>${an.name}</span><div class="chart-track"><span style="width:${r.percentages[i]}%;background:${i===r.type-1?'#fc6b26':'#f8ba95'}"></span></div><strong>${r.percentages[i]}%</strong></div>`).join('')}</div><p class="result-note">대표 유형은 가장 많이 선택한 동물, 윙(W)은 양옆 유형 중 더 많이 선택한 유형입니다. 비율은 선택 문장의 구성비이며, 성격의 확률이나 전문 진단 결과를 의미하지 않습니다.</p></section>${r.ties.length>1||r.wingCandidates.length>1?`<div class="tie-settings"><p>${r.ties.length>1?'가장 높은 점수가 같은 동물이 있어요. 더 닮았다고 느끼는 친구를 대표로 골라보세요.':'양옆 유형의 점수가 같아요. 더 닮았다고 느끼는 윙을 골라보세요.'}</p>${r.ties.length>1?`<label>대표 동물 <select data-type>${r.ties.map(id=>`<option value="${id}" ${id===r.type?'selected':''}>${animals[id-1].name} (${id}유형)</option>`).join('')}</select></label>`:''}${r.wingCandidates.length>1?`<label>윙 <select data-wing>${r.wingCandidates.map(id=>`<option value="${id}" ${id===r.wing?'selected':''}>${animals[id-1].name} (W${id})</option>`).join('')}</select></label>`:''}<small>동점일 때는 번호가 작은 유형을 먼저 표시합니다. ${r.wingCandidates.every(id=>r.scores[id-1]===0)?'양옆 유형에 응답이 없어 윙은 잠정 표시입니다.':''}</small></div>`:''}<div class="result-actions"><button class="button orange" data-export="image">${icon('download')} 이미지 저장</button><button class="button outline" data-export="pdf">${icon('download')} PDF 저장</button><button class="button outline" data-share>${icon('share')} 결과 공유</button></div><div class="share-box" hidden><h3>나의 발견을 나눠보세요</h3><div class="share-link"><input readonly aria-label="공유할 결과 링크" value=""><button class="button small dark" data-copy>링크 복사</button></div><div class="social-links"><a data-social="x" target="_blank" rel="noopener noreferrer">X에 공유</a><a data-social="facebook" target="_blank" rel="noopener noreferrer">Facebook에 공유</a><button data-native-share>다른 앱으로 공유</button></div><p>공유 링크에는 동물별 선택 수와 대표 유형·윙만 포함됩니다.</p></div><div class="result-bottom"><button class="text-link" data-reset>다시 검사하기</button>${link('/education/','나를 더 깊이 알아가는 교육','text-link')}</div></main>${footer(true)}`}
function resultFromURL(){const p=new URLSearchParams(location.search);if(!p.has('s'))return null;const s=p.get('s');if(!/^[0-5]{9}$/.test(s))return false;try{return calculateResult(s.split('').map(Number),Number(p.get('t')),Number(p.get('w')))||false}catch{return false}}
function shareURL(r){return `${location.origin}${basePath}result/?s=${r.scores.join('')}&t=${r.type}&w=${r.wing}`}
function scrollToAnchor(behavior='instant'){if(!location.hash)return;let id;try{id=decodeURIComponent(location.hash.slice(1))}catch{return}document.getElementById(id)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':behavior})}
function go(url){history.pushState({},'',appURL(url));render();window.scrollTo({top:0,behavior:'instant'});if(location.hash)requestAnimationFrame(()=>scrollToAnchor('smooth'))}
let currentResult;
function render(){window.gsap?.killTweensOf(app.querySelectorAll('*'));window.ScrollTrigger?.getAll().forEach(t=>t.kill());let html;let route=location.pathname.slice(basePath.length-1).replace(/\/$/,'');currentResult=null;if(route==='/education'){html=education();document.title='교육 소개 | 애니어그램 인사이트'}else if(route==='/lectures'){html=lectures();document.title='강연 소개 | 애니어그램 인사이트'}else if(route==='/contact'){html=contactPage({header,footer,icon,link,clayImage});document.title='문의하기 | 애니어그램 인사이트'}else if(route==='/test'){html=phase==='questions'?questions():intro();document.title='나의 동물 유형 찾기 | animal insight'}else if(route==='/result'){const r=resultFromURL();if(r){currentResult=r;html=resultView(r);document.title=`${r.type}W${r.wing} ${animals[r.type-1].name} | 나의 동물 유형`}else{html=`${header(true)}<main id="main" class="empty-state"><h1>결과를 찾을 수 없어요.</h1><p>검사를 완료하거나 올바른 결과 링크를 열어주세요.</p>${link('/test/','검사 시작하기','button orange')}</main>${footer(true)}`}}else{html=home();document.title='애니어그램 인사이트 — 나를 발견하는 새로운 시선'}app.innerHTML=localizeMarkup(html);bind();animate();bindImages()}
function bindImages(root=app){root.querySelectorAll('img').forEach(img=>{img.decoding='async';if(img.loading==='lazy')img.loading='eager';img.addEventListener('load',()=>window.ScrollTrigger?.refresh(),{once:true});img.addEventListener('error',()=>{if(img.dataset.retried)return;img.dataset.retried='true';const original=img.getAttribute('src');setTimeout(()=>{if(img.isConnected)img.src=original+(original.includes('?')?'&':'?')+'retry=1'},600)},{once:true})})}
function bind(){app.querySelectorAll('[data-copy-detail]').forEach(button=>button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(button.dataset.copyDetail);toast('복사했어요.')}catch{toast('복사하지 못했어요. 아래 정보를 직접 선택해주세요.')}}));app.querySelectorAll('[data-link]').forEach(a=>a.addEventListener('click',e=>{if(e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;const url=new URL(a.href);if(url.origin!==location.origin)return;e.preventDefault();if(url.pathname===location.pathname&&url.hash){history.pushState({},'',url.pathname+url.hash);document.querySelector(url.hash)?.scrollIntoView({behavior:'smooth'});app.querySelector('.header').classList.remove('menu-open');return}go(url.pathname+url.search+url.hash)}));app.querySelector('.menu-toggle')?.addEventListener('click',e=>{const open=app.querySelector('.header').classList.toggle('menu-open');const b=e.currentTarget;b.setAttribute('aria-expanded',String(open));b.setAttribute('aria-label',open?'메뉴 닫기':'메뉴 열기');b.innerHTML=icon(open?'close':'menu')});app.querySelectorAll('[data-animal]').forEach(b=>b.addEventListener('click',()=>openAnimal(Number(b.dataset.animal))));app.querySelector('[data-start]')?.addEventListener('click',()=>{phase='questions';render();window.scrollTo(0,0)});app.querySelector('[data-intro]')?.addEventListener('click',e=>{e.preventDefault();phase='intro';render()});app.querySelectorAll('[data-reset]').forEach(b=>b.addEventListener('click',()=>{answers=Array.from({length:9},()=>[]);visited=Array(9).fill(false);step=0;phase='intro';saveDraft();go('/test/')}));app.querySelector('[data-prev]')?.addEventListener('click',()=>{if(step)step--;else phase='intro';saveDraft();render();window.scrollTo(0,0)});app.querySelectorAll('.answer-option input').forEach(input=>input.addEventListener('change',()=>{if(input.value==='none'){answers[step]=[];visited[step]=input.checked}else{const value=Number(input.value);answers[step]=input.checked?[...new Set([...answers[step],value])]:answers[step].filter(v=>v!==value);visited[step]=answers[step].length>0;app.querySelector('[value="none"]').checked=false}app.querySelectorAll('.answer-option input:not([value="none"])').forEach(i=>i.checked=answers[step].includes(Number(i.value)));app.querySelector('.quiz-actions>span').textContent=`${answers[step].length}개 선택`;app.querySelector('.quiz-error').textContent='';saveDraft()}));app.querySelector('[data-next]')?.addEventListener('click',()=>{const error=app.querySelector('.quiz-error');if(!visited[step]){error.textContent='닮은 문장을 선택하거나, ‘해당하는 문장 없음’을 선택해주세요.';return}if(step<8){step++;saveDraft();render();window.scrollTo(0,0)}else{const r=calculateResult(answers.map(a=>a.length));if(!r){error.textContent='모든 유형에서 선택한 문장이 없어요. 이전 단계에서 나와 닮은 문장을 찾아주세요.';return}const missing=visited.indexOf(false);if(missing>=0){step=missing;render();return}go('/result/?s='+r.scores.join('')+'&t='+r.type+'&w='+r.wing)}});app.querySelectorAll('[data-export]').forEach(b=>b.addEventListener('click',()=>exportResult(b.dataset.export,b)));app.querySelector('[data-share]')?.addEventListener('click',()=>{const box=app.querySelector('.share-box');box.hidden=!box.hidden;if(!box.hidden){const url=shareURL(currentResult);box.querySelector('input').value=url;box.querySelector('[data-social="x"]').href='https://twitter.com/intent/tweet?text='+encodeURIComponent(`나를 닮은 친구는 ${animals[currentResult.type-1].name}! ${currentResult.type}W${currentResult.wing}`)+'&url='+encodeURIComponent(url);box.querySelector('[data-social="facebook"]').href='https://www.facebook.com/sharer/sharer.php?u='+encodeURIComponent(url);box.scrollIntoView({behavior:'smooth',block:'nearest'})}});app.querySelector('[data-copy]')?.addEventListener('click',async()=>{const input=app.querySelector('.share-link input');try{await navigator.clipboard.writeText(input.value);toast('결과 링크를 복사했어요.')}catch{input.focus();input.select();toast('선택된 링크를 복사해주세요.')}});app.querySelector('[data-native-share]')?.addEventListener('click',async()=>{if(navigator.share){try{await navigator.share({title:'나의 동물 유형',text:`나를 닮은 친구는 ${animals[currentResult.type-1].name}!`,url:shareURL(currentResult)})}catch(e){if(e.name!=='AbortError')toast('공유를 완료하지 못했어요. 링크 복사를 이용해주세요.')}}else app.querySelector('[data-copy]').click()});app.querySelector('[data-type]')?.addEventListener('change',e=>{const r=calculateResult(currentResult.scores,Number(e.target.value));go('/result/?s='+r.scores.join('')+'&t='+r.type+'&w='+r.wing)});app.querySelector('[data-wing]')?.addEventListener('change',e=>{const r=calculateResult(currentResult.scores,currentResult.type,Number(e.target.value));go('/result/?s='+r.scores.join('')+'&t='+r.type+'&w='+r.wing)})}
function openAnimal(id){const a=animals[id-1];const dialog=document.createElement('dialog');dialog.className='animal-dialog';dialog.innerHTML=localizeMarkup(`<button class="icon-button dialog-close" aria-label="닫기">${icon('close')}</button><div class="dialog-art" style="background:${a.color}">${image(a)}</div><span class="eyebrow">TYPE ${String(id).padStart(2,'0')}</span><h2>${a.title}</h2><p class="orange-text">${a.tag}</p><p>${a.description}</p>${link('/test/','나와 얼마나 닮았는지 알아보기','button orange')}`);document.body.append(dialog);dialog.showModal();bindImages(dialog);dialog.querySelector('.dialog-close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close()}});dialog.addEventListener('close',()=>dialog.remove());dialog.querySelector('[data-link]').onclick=e=>{e.preventDefault();dialog.close();go('/test/')}}
let toastTimer;function toast(text){const box=document.querySelector('#toast');box.textContent=text;box.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.classList.remove('visible'),3500)}
async function exportResult(format,button){if(!window.html2canvas||!window.jspdf){toast('저장 기능을 불러오지 못했어요. 새로고침 후 다시 시도해주세요.');return}const original=button.innerHTML;button.disabled=true;button.textContent='저장 준비 중…';try{await document.fonts.ready;const card=document.querySelector('#result-card');await Promise.all([...card.querySelectorAll('img')].map(img=>img.decode()));const canvas=await window.html2canvas(card,{scale:2,backgroundColor:'#ffffff',useCORS:true,logging:false,windowWidth:Math.max(1000,window.innerWidth)});const filename=`나의-동물유형-${currentResult.type}W${currentResult.wing}`;if(format==='image'){const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw new Error('이미지 생성 실패');const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=filename+'.png';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}else{const {jsPDF}=window.jspdf;const pdf=new jsPDF({unit:'mm',format:'a4',compress:true});const width=190,height=canvas.height/canvas.width*width;const available=277;const factor=Math.min(1,available/height);pdf.addImage(canvas.toDataURL('image/jpeg',.92),'JPEG',(210-width*factor)/2,10,width*factor,height*factor);pdf.save(filename+'.pdf')}toast(format==='image'?'결과 이미지를 저장했어요.':'결과 PDF를 저장했어요.')}catch(e){console.error(e);toast('결과를 저장하지 못했어요. 잠시 후 다시 시도해주세요.')}finally{button.disabled=false;button.innerHTML=original}}
function animate(){runMotion()}
window.addEventListener('popstate',render);document.addEventListener('keydown',e=>{if(e.key==='Escape'){app.querySelector('.header')?.classList.remove('menu-open');const b=app.querySelector('.menu-toggle');if(b){b.setAttribute('aria-expanded','false');b.innerHTML=icon('menu')}}});render();document.fonts.ready.then(()=>requestAnimationFrame(()=>{window.ScrollTrigger?.refresh();scrollToAnchor()}));
